'山影不随云影转，竹声长作雨声来',
'十里江风吹昼梦，一川梅雨敌春愁',
'龙睡有时悭小雨，春长无地觅灵苖',
'斜雨逆风昏旧字，是中能有几人知',
'江云不与山云接，土雨还因夜雨消',
'水曺载酒非无意，小雨留人信有缘',
'向道在家贫亦好，恶教风雨送归来',
'江上归来无好思，满庭风雨易黄昏',
'春雨一溪藏钓艇，秋风十里对荷花',
'天公与此强健身，故遣雨洗南徐春',
'塞云常雨雪，山木自多风',
'春雨秋风无尽期，鸢飞鱼跃各天机',
'云雷一夜起，风雨满山寒',
'秋雨松林成水墨，春风花谷具丹青',
'花枝欲动濡须坞，无赖春风吹小雨',
'疾雷过耳不及掩，澍雨翻盆何自来',
'及此瓦盆春酒满，烧灯夜雨重论文',
'雨雪一番今浄尽，候禽无数唤春声',
'云气愁人故不开，风吹雨脚著莓苔',
'讵知时雨灵，但觉中酒圣',
'非关风雨留连我，要作山间十日留',
'风枝雨叶春无赖，石径芳茨昼不开',
'久雨不晴今日晴，和泥合水要分明',
'岂不惜嘉阴，奈此风雨何',
'道人竹瘦松柏刚，饱更风雨惯雪霜',
'夜来雨过菖蒲静，倒浸中天四五星',
'问道故人归雨后，供香童子立更深',
