'飞絮落花何足道，忽经风雨亦添愁',
'雨夜宿山斋，夜深雨声息',
'明朝回首江南岸，烟雨昏昏不见人',
'风雨无时浪蹴天，南浮舟楫信多艰',
'半檐落日飞花后，一阵轻寒微雨时',
'杨花扰乱少年心，怕雨愁风用意深',
'清明已过三春候，谷雨初晴四月天',
'满地落花初过雨，一声啼鸟已春归',
'连理枝头花正开，妒花风雨苦相催',
'明朝春在雨中看，心碎檐声点滴间',
'竹窗萧索镇如秋，雨滴檐花夜不休',
'更堪细雨新秋夜，一点残灯伴夜长',
'往来泥雨城南路，可见轻鸥定不凡',
'风摇柳带千丝乱，雨勒花心十日期',
'想见江郎闭船卧，满川风雨报天明',
'须公一勺羔儿酒，伴我夜窗听雨声',
'无限客愁芳草里，不知风雨阻斜阳',
'雨中寒芦披靡去，天际风帆先后归',
'他日无人识佳景，满城风雨近重阳',
'乃知风雨昼窈冥，我亦不废晨鸡鸣',
'我自不能知许事，暮江斜雨送蛙声',
'悬知先入他年话，一夜蛙声连雨声',
'细雨不成雪，北风来解纷',
'海陵三月与春别，一夜雨成三尺泥',
'风雨属连春事休，十日九日转城头',
'晚来一雨天遂凉，便思约君来对床',
'正是水西佳绝处，不辞风雨夜深寒',
'叠嶂雨来如画里，敬亭秋入胜花时',
'何以至人常不出，看人冲雨度浮航',
'雨侵田水连溪白，春入山花带蜜香',
