'霜风过雨不胜寒，木落重重见远山',
'潮涨添春雨，山明放野花',
'夜堂人静雨霏霏，润泽焦枯总不知',
'云山幸不持钱买，花竹何妨带雨移',
'它时傥记江南梦，画我黄梅细雨中',
'清梦不成风雨夜，更堪诗思搅饥肠',
'归来醉撚一枝春，照影凉蟾过雨新',
'只应连夜雨，又过一年春',
'山头一寸云，山下一尺雨',
'谓天为不仁，春夏雨如彼',
'若无三日雨，那复一年秋',
'无路从公上烟雨，梦魂长绕处州山',
'风雨萧萧鸡自晓，此心常与子周旋',
'水似篙深催我去，雨如丝下要人留',
'满城风雨无杯酒，故国松楸欠纸钱',
'谁言春雨散如丝，一月垂空似绠縻',
'观水观山都废食，听风听雨不妨眠',
'染时定着蔷薇露，雨洗风吹故自香',
'一年春事顿成空，不必飘零似红雨',
'留得甘泉作霖雨，白云来往自无心',
'十日一风五日雨，邻村稽首羡兹土',
'秪从精祷召神灵，五日一风十日雨',
'风雨年年横，莺花处处残',
'一犂雨向田间足，万里春从天际来',
'人人凖拟为霖甚，风动雷行雨却无',
'雨师不得逞，风伯无所施',
'适当秾华时，明知不须雨',
'此道果有继，不忧风雨侵',
'采花供课能满庾，不自营巢庇风雨',
'晴时得雨静招风，若饮清凉汗如雨',
'时当恢台积氛雾，一日三雨时三停',
'一晴一雨告休咎，晴者人乐阴天刑',
'头如青山手如雨，十日瓦沟鸣羯鼓',
'开正尽数一至七，无雨无风保休吉',
'有时去作人间雨，无事不闻斋后禽',
'却恨经春长闭户，等闲风雨不离家',
