'翁今有弟夜雨对床乐，颇胜卯君怀远驿中有感秋风起',
'清秋方初兮霪雨降而无时，旧坊弗治兮河水泛滥而为灾',
'雨三休兮神三燕，游云高兮见极蒲，安我舟楫兮君不怒',
'结融肖像彩介朱鬣宛如昨，风醒雨涩森然向人恐遂跃',
'歌断宴阑，荣华露草，冷落山丘，到此徘徊，细雨西城，羊昙醉后花飞',
'江南憔悴，荒村流落，伤心自失梨园部，渺空江、泪隔芦花雨',
'忽雷霹雳卒风暴雨撼不动，欲动不动千变万化总是鳞皴皮',
'天若雨珠真可噱，请以缀衮冕之十二旒，龙旗和鸾之缨络',
'芦笔书空兮风凄凄，竹墨泌地兮雨垂垂，青枫黑塞兮梦公者谁',
'诗题：再过泗上二首首句：眼明初见淮南树系舟淮北雨折轴',
'远壑夕阳残雨后，作数抹夕阳残雨外一番飞絮满江城',
'陡寒还热，急雨随晴，化工无准，将息偏难，更向分携处、立多时',
'叹寂寞尘埃满眼，梦逐孤云缥缈，春潮带雨，鸥迎远溆，雁别平沙',
'斗鸡走狗，呼卢蹴鞠，平生把臂江湖旧，约何时、共话连床雨',
'辘轳金井梧桐晚，几树惊秋，昼雨如愁，百尺虾须上玉钩',
'苹初至镇，易禹庙金紫服以冠冕，后因祈雨，作此诗，其和者盐铁转运崔述等凡十七首',
'枕白石兮漱清流，芦声战雨曷若飏风之拔木，渔烟凝晚曷若海雾之横秋',
'鸣皋少室峥嵘倚天阙，下有回渊万仞蟠双龙，蒸云结雨气蒙蒙',
'雨多屋漏泥土落，尔莫厌老翁茅屋低，梁头作窠梁下栖',
